/** The app's own elements (`app.add_react_element`). Augments the
 *  `BevyIntrinsicElements` interface in the `bevy-react` package, so JSX
 *  types them. */
declare module "bevy-react" {
  interface BevyIntrinsicElements {
    anchor: BevyAnchorProps;
    canvas: BevyCanvasProps;
    circle: BevyCircleProps;
    ellipse: BevyEllipseProps;
    g: BevyGProps;
    line: BevyLineProps;
    path: BevyPathProps;
    polygon: BevyPolygonProps;
    polyline: BevyPolylineProps;
    portal: BevyPortalProps;
    rect: BevyRectProps;
    surface: BevySurfaceProps;
    svg: BevySvgProps;
  }
}

/** Send a typed app message to the Bevy side. */
export function emit<K extends keyof ReactMessages>(name: K, value: ReactMessages[K]): void {
  rawEmit(name, value);
}

/** Send a typed request and await its typed response. */
export function request<K extends keyof ReactRequests>(
  name: K,
  value: ReactRequests[K]["request"],
): Promise<ReactRequests[K]["response"]> {
  return rawRequest(name, value) as Promise<ReactRequests[K]["response"]>;
}

/** Subscribe to a typed Bevy → React event. Returns an unsubscribe fn. */
export function on<K extends keyof ReactEvents>(
  name: K,
  cb: (value: ReactEvents[K]) => void,
): () => void {
  rawAddEventListener(name, cb as (value: unknown) => void);
  return () => rawRemoveEventListener(name, cb as (value: unknown) => void);
}

/** Unsubscribe a listener previously passed to `on`/`addEventListener`. */
export function removeEventListener<K extends keyof ReactEvents>(
  name: K,
  cb: (value: ReactEvents[K]) => void,
): void {
  rawRemoveEventListener(name, cb as (value: unknown) => void);
}

/** Structured, fully typed proxy over every message, request, and event. */
export const bevy = {
  emit,
  request,
  on,
  addEventListener: on,
  removeEventListener,
  app: {
    info(): Promise<AppInfo> { return request("app.info", null); },
    quit(value: AppQuit): void { emit("app.quit", value); },
    snapshot(): Promise<AppStatus> { return request("app.snapshot", null); },
  },
  bindings: {
    get(): Promise<UiBindings> { return request("bindings.get", null); },
  },
  catalog: {
    get(): Promise<UiCatalog> { return request("catalog.get", null); },
  },
  editor: {
    command(value: EditorCommandMsg): void { emit("editor.command", value); },
    options(value: EditorSetOptions): void { emit("editor.options", value); },
    select(value: EditorSelect): void { emit("editor.select", value); },
    set(value: EditorSet): void { emit("editor.set", value); },
    snapshot(): Promise<EditorStatus | null> { return request("editor.snapshot", null); },
  },
  gamepad: {
    getAll(): Promise<Array<GamepadConnectedData>> { return request("gamepad.getAll", null); },
    rumble(value: GamepadRumble): void { emit("gamepad.rumble", value); },
    stopRumble(value: GamepadStopRumble): void { emit("gamepad.stopRumble", value); },
  },
  hud: {
    bind(value: BindHud): void { emit("hud.bind", value); },
    unbind(value: UnbindHud): void { emit("hud.unbind", value); },
  },
  input: {
    dropPlayer(value: DropPlayer): void { emit("input.dropPlayer", value); },
    rebind(value: Rebind): void { emit("input.rebind", value); },
    resetBindings(value: ResetBindings): void { emit("input.resetBindings", value); },
  },
  lobby: {
    close(value: CloseLobby): void { emit("lobby.close", value); },
    open(value: OpenLobby): void { emit("lobby.open", value); },
    snapshot(): Promise<UiLobby> { return request("lobby.snapshot", null); },
  },
  menu: {
    backdrop(value: SetBackdrop): void { emit("menu.backdrop", value); },
  },
  profile: {
    get(): Promise<UiProfile> { return request("profile.get", null); },
    reset(value: ResetProgress): void { emit("profile.reset", value); },
    seen(value: MarkSeen): void { emit("profile.seen", value); },
  },
  race: {
    next(value: NextRace): void { emit("race.next", value); },
    nextTrack(value: NextTrack): void { emit("race.nextTrack", value); },
    quit(value: QuitRace): void { emit("race.quit", value); },
    rematch(value: Rematch): void { emit("race.rematch", value); },
    restart(value: RestartRace): void { emit("race.restart", value); },
    resume(value: ResumeRace): void { emit("race.resume", value); },
    snapshot(): Promise<UiRaceSession> { return request("race.snapshot", null); },
    start(value: StartRace): void { emit("race.start", value); },
  },
  records: {
    get(): Promise<UiRecords> { return request("records.get", null); },
  },
  settings: {
    apply(value: ApplySettings): void { emit("settings.apply", value); },
    get(): Promise<UiSettings> { return request("settings.get", null); },
  },
  ui: {
    error(value: UiError): void { emit("ui.error", value); },
    ready(value: UiReady): void { emit("ui.ready", value); },
    screen(value: UiScreen): void { emit("ui.screen", value); },
    sound(value: PlayCue): void { emit("ui.sound", value); },
    stinger(value: PlayStinger): void { emit("ui.stinger", value); },
  },
  window: {
    size(): Promise<WindowSize> { return request("window.size", null); },
  },
} as const;
